command:
printf 'NODE_NAME=%s NODE_IP=%s
' "$NODE_NAME" "$NODE_IP"; curl -fsS --max-time 10 -o /dev/null -w 'loopback_http_code=%{http_code} remote_ip_http_code=%{remote_ip} connect=%{time_connect} total=%{time_total}
' http://127.0.0.1:6700/; rc1=$?; curl -fsS --max-time 10 -o /dev/null -w 'managed_http_code=%{http_code} remote_ip=%{remote_ip} connect=%{time_connect} total=%{time_total}
' "http://$NODE_IP:6700/"; rc2=$?; printf 'loopback_curl_rc=%s managed_curl_rc=%s
' "$rc1" "$rc2"; [ "$rc1" -eq 0 ] && [ "$rc2" -eq 0 ]

